Q: How do you get p5.js into a website? A: <pre><code>&lt;!DOCTYPE html&gt;
&lt;html&gt;
&lt;head&gt;
&lt;meta charset=&quot;UTF-8&quot;&gt;
&lt;title&gt;Kernel Defender&lt;/title&gt;
&lt;script src=&quot;https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.6.0/p5.min.js&quot;&gt;&lt;/script&gt;
&lt;style&gt;body{margin:0;overflow:hidden;background:black;color:lime;font-family:monospace;}#highscore{position:absolute;top:10px;right:20px;color:lime;}&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
&lt;div id=&quot;highscore&quot;&gt;High Score: 0&lt;/div&gt;
&lt;script&gt;
let server, greenPackets=[], redPackets=[], patchPowerUps=[], firewallShots=[], boss;
let score=0, health=3, level=1, speed=3, highScore=0, bossActive=false, bossHealth=15;
let gameOver=false, bossDefeated=false;
function setup(){
  createCanvas(600,400);
  server=new Server(width/2,height-50,50,30);
}
function draw(){
  background(0);
  if(!gameOver){
    server.show();
    server.move();
    handlePackets();
    handlePowerUps();
    handleFirewall();
    handleBoss();
    drawUI();
    updateLevel();
  } else {
    textAlign(CENTER,CENTER);
    textSize(40); fill('red');
    text('KERNEL PANIC!',width/2,height/2);
    textSize(20); fill('lime');
    text('Press R to Restart',width/2,height/2+50);
  }
}
function keyPressed(){
  if(key==' '){firewallShots.push(new FirewallShot(server.x,server.y-20));}
  if(gameOver &amp;&amp; (key=='r' || key=='R')){restartGame();}
}
function handlePackets(){
  if(frameCount%60==0){greenPackets.push(new Packet(random(width),0,20,'green'))}
  if(frameCount%(90-speed*5)==0){redPackets.push(new Packet(random(width),0,20,'red'))}
  for(let p of greenPackets){p.show(); p.update(); if(p.hit(server)){score+=1; p.remove=true;}}
  for(let p of redPackets){p.show(); p.update(); if(p.hit(server)){health-=1; p.remove=true;}}
  greenPackets=greenPackets.filter(p=&gt;!p.remove);
  redPackets=redPackets.filter(p=&gt;!p.remove);
  if(health&lt;=0){gameOver=true;if(score&gt;highScore){highScore=score;document.getElementById('highscore').innerHTML='High Score: '+highScore;}}
}
function handlePowerUps(){
  if(frameCount%600==0){patchPowerUps.push(new Patch(random(width),0,20));}
  for(let p of patchPowerUps){p.show(); p.update(); if(p.hit(server)){redPackets=[]; p.remove=true;}}
  patchPowerUps=patchPowerUps.filter(p=&gt;!p.remove);
}
function handleFirewall(){
  for(let f of firewallShots){f.show(); f.update(); if(bossActive &amp;&amp; f.hit(boss)){bossHealth--; f.remove=true;}}
  firewallShots=firewallShots.filter(f=&gt;!f.remove);
}
function handleBoss(){
  if(level&gt;=3 &amp;&amp; !bossActive){boss=new Boss(width/2,50,80,50); bossActive=true;}
  if(bossActive &amp;&amp; !bossDefeated){boss.show(); boss.update(); boss.attack(server,redPackets); if(bossHealth&lt;=0){bossDefeated=true; bossActive=false;}}
}
function drawUI(){
  fill('lime'); textSize(16); text('Score: '+score,10,20); text('Health: '+health,10,40); text('Level: '+level,10,60); text('Boss Health: '+(bossActive?bossHealth:0),10,80);
  fill('green'); rect(100,10,health*30,10);
}
function updateLevel(){
  if(score&gt;25){level=3; speed=5;} else if(score&gt;10){level=2; speed=4;}
}
function restartGame(){
  score=0; health=3; level=1; speed=3; bossActive=false; bossDefeated=false; greenPackets=[]; redPackets=[]; patchPowerUps=[]; firewallShots=[]; gameOver=false;
}
class Server{
  constructor(x,y,w,h){this.x=x;this.y=y;this.w=w;this.h=h;}
  show(){fill('blue'); rectMode(CENTER); rect(this.x,this.y,this.w,this.h);}
  move(){if(keyIsDown(LEFT_ARROW)){this.x-=5} if(keyIsDown(RIGHT_ARROW)){this.x+=5} this.x=constrain(this.x,this.w/2,width-this.w/2);}
}
class Packet{
  constructor(x,y,s,type){this.x=x; this.y=y; this.s=s; this.type=type; this.remove=false;}
  show(){fill(this.type); ellipse(this.x,this.y,this.s);}
  update(){this.y+=this.type=='green'?speed:speed+1; if(this.y&gt;height){this.remove=true;}}
  hit(obj){return collideRectCircle(obj.x-obj.w/2,obj.y-obj.h/2,obj.w,obj.h,this.x,this.y,this.s);}
}
class Patch{
  constructor(x,y,s){this.x=x; this.y=y; this.s=s; this.remove=false;}
  show(){fill('yellow'); ellipse(this.x,this.y,this.s);}
  update(){this.y+=2; if(this.y&gt;height){this.remove=true;}}
  hit(obj){return collideRectCircle(obj.x-obj.w/2,obj.y-obj.h/2,obj.w,obj.h,this.x,this.y,this.s);}
}
class FirewallShot{
  constructor(x,y){this.x=x;this.y=y;this.s=10;this.remove=false;}
  show(){fill('cyan'); ellipse(this.x,this.y,this.s);}
  update(){this.y-=7; if(this.y&lt;0){this.remove=true;}}
  hit(boss){if(!boss) return false; if(collideRectCircle(boss.x-boss.w/2,boss.y-boss.h/2,boss.w,boss.h,this.x,this.y,this.s)){return true;} return false;}
}
class Boss{
  constructor(x,y,w,h){this.x=x;this.y=y;this.w=w;this.h=h; this.dir=1;}
  show(){fill('red'); rectMode(CENTER); rect(this.x,this.y,this.w,this.h);}
  update(){this.x+=this.dir*2; if(this.x&lt;this.w/2||this.x&gt;width-this.w/2){this.dir*=-1;}}
  attack(server,redPackets){if(frameCount%60==0){redPackets.push(new Packet(this.x,this.y,20,'red'));}}
}
&lt;/script&gt;
&lt;script src=&quot;https://cdn.jsdelivr.net/npm/p5.collide2d@0.7.3/p5.collide2d.min.js&quot;&gt;&lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

Q: Concurrent cache using SoftReferences behaves unpredictably under memory pressure, how to fix? A: <p>There is a race condition resulting in removal of up-to-date references from cache:</p>
<pre><code>jshell&gt; import java.util.concurrent.ConcurrentHashMap;
jshell&gt; var m = new java.util.concurrent.ConcurrentHashMap&lt;Integer, Integer&gt;();
m ==&gt; {}
jshell&gt; m.put(1, 10);
$3 ==&gt; null
jshell&gt; m.put(2, 20);
$4 ==&gt; null
jshell&gt; var i = m.entrySet().iterator(); // Cleanup start
i ==&gt; java.util.concurrent.ConcurrentHashMap$EntryIterator@5197848c
jshell&gt; var e = i.next();
e ==&gt; 1=10
jshell&gt; m.put(1, 30); // Imitating another thread modifying the value
$8 ==&gt; 10
jshell&gt; m
m ==&gt; {1=30, 2=20}
jshell&gt; e.getValue() // Checking if a value should be removed
$10 ==&gt; 10
jshell&gt; i.remove();  // Trying to remove value 10
jshell&gt; m
m ==&gt; {2=20} // Value 30 is removed instead of 10 due to snapshot-based race
</code></pre>
<p>Use two-argument removal <a href="https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/util/concurrent/ConcurrentHashMap.html#remove(java.lang.Object,java.lang.Object)" rel="nofollow noreferrer">public boolean remove(Object key, Object value)</a> for CAS removals.</p>

Q: Memory Leak using Tries - pset5 cs50 - dictionary.c A: <p>In analyzing your issue, the good comments do point to the likely issue of not having the children node pointers initialized when memory for a new node structure is allocated.  If one doesn't have Valgrind available, an alternative method is to compile with the sanitizer flag as in the following example.</p>
<pre><code>-fsanitize=address
</code></pre>
<p>When I recompiled the above code along with the helper code and then ran the program, I received the following terminal output indicating an issue with possible undefined memory addresses.</p>
<pre><code>craig@Vera:~/C_Programs/Console/Spell_13/bin/Release$ ./Spell_13 Stuff.txt Tests.txt
AddressSanitizer:DEADLYSIGNAL
=================================================================
==3894==ERROR: AddressSanitizer: SEGV on unknown address (pc 0x5582ecdde07d bp 0x515000000080 sp 0x7fff6de636d0 T0)
==3894==The signal is caused by a READ memory access.
==3894==Hint: this fault was caused by a dereference of a high value address (see register values below).  Dissassemble the provided pc to learn which register was used.
    #0 0x5582ecdde07d  (/home/craig/C_Programs/Console/Spell_13/bin/Release/Spell_13+0x307d)
    #1 0x5582ecddd5a7  (/home/craig/C_Programs/Console/Spell_13/bin/Release/Spell_13+0x25a7)
    #2 0x7f9db1335d8f in __libc_start_call_main ../sysdeps/nptl/libc_start_call_main.h:58
    #3 0x7f9db1335e3f in __libc_start_main_impl ../csu/libc-start.c:392
    #4 0x5582ecddd884  (/home/craig/C_Programs/Console/Spell_13/bin/Release/Spell_13+0x2884)

AddressSanitizer can not provide additional info.
SUMMARY: AddressSanitizer: SEGV (/home/craig/C_Programs/Console/Spell_13/bin/Release/Spell_13+0x307d) 
==3894==ABORTING
</code></pre>
<p>Responding to the good comments, at the point of memory allocation within the dictionary build function, the code was refactored to include initialization of the children node pointers.</p>
<pre><code>    root = malloc(sizeof(node));
    nodes_loaded++;
    if (root == NULL)
    {
        unload();
        fclose(dict);
        return false;
    }

    for (int i = 0; i &lt; ALPHABETSIZE; i++)
        root-&gt;children[i] = NULL;               /* Initialize children node pointers    */
</code></pre>
<pre><code>    for (int i = 0; i &lt; ALPHABETSIZE; i++)
        root-&gt;children[i] = NULL;               /* Initialize children node pointers    */

    if (now-&gt;children[k] == NULL)
    {
        node* new_node = malloc(sizeof(node));

        for (int i = 0; i &lt; ALPHABETSIZE; i++)
            new_node-&gt;children[i] = NULL;       /* Initialize children node pointers    */

        now-&gt;children[k] = new_node;
        nodes_loaded++;                         /* Keep stats on memory allocation      */
    }
</code></pre>
<p>Along with that, a couple of additional counter variables were added along with a statistics function to note how many node structures were allocated and freed.</p>
<pre><code>int num_of_words = 0, words_freed = 0, nodes_loaded = 0;
</code></pre>
<pre><code>void unloadNode(node* next)
{
    // call unloadNode on every node in this node's children
    for(int i = 0; i &lt; ALPHABETSIZE; i++)
    {
        if(next-&gt;children[i] != NULL)
        {
            unloadNode(next-&gt;children[i]);
        }
    }

    // once the children nodes are freed, free this node
    free(next);
    words_freed++;  /* Tally number of addresses freed  */
}
</code></pre>
<pre><code>void stats(void)
{
    printf(&quot;Nodes allocated: %d  Nodes freed: %d\n&quot;, nodes_loaded, words_freed);
}
</code></pre>
<p>With that, a retest of the code with the appropriate initialization refactoring allowed the program to process without address issues.</p>
<pre><code>craig@Vera:~/C_Programs/Console/Spell_13/bin/Release$ ./Spell_13 Stuff.txt Tests.txt

